import test from 'node:test';
import assert from 'node:assert/strict';
import { sqliteFixture } from './sarin-sqlite-fixture.mjs';
import { createWhatsAppIngressStore } from '../../server/sarin/whatsapp/ingress-store.js';
import { createWhatsAppWorkStore } from '../../server/sarin/whatsapp/work-store.js';
async function setup(t){
 const f=await sqliteFixture({whatsapp:true,replies:true});t.after(f.close);let at=Date.UTC(2026,9,18,12),seq=0;
 const now=()=>at,store=createWhatsAppWorkStore({db:f.db,now}),ingress=createWhatsAppIngressStore({db:f.db,now});
 async function capture(kind='inbound',wamid){at+=1000;seq++;const e={kind,eventId:'evt_'+seq,messageId:'msg_'+seq,wamid:wamid??'wamid.'+seq,wabaId:'12345',from:kind==='inbound'?'+573000000001':'+573000000002',to:kind==='inbound'?'+573000000002':'+573000000001',sentAt:at,createdAt:at,mediaType:'text',text:'Proyecto ficticio'};await ingress.capture(e);return e;}
 await capture();const peerKey=f.sqlite.prepare('SELECT peer_key FROM sarin_wa_inbox').get().peer_key;
 await store.setPilotMode({enabled:true,expectedRevision:0,actor:'test'});await store.resumePeer({peerKey,expectedRevision:0,actor:'test'});
 const e=await capture(),j=f.sqlite.prepare('SELECT * FROM sarin_wa_jobs WHERE event_id=?').get(e.eventId),token=crypto.randomUUID();await store.claimGeneration({jobId:j.job_id,epoch:j.epoch,token});
 const out=await store.createFixedReply({jobId:j.job_id,token,purpose:'notice',text:'Aviso sintetico',version:'v1',hash:'a'.repeat(64)});
 const permit=await store.beginSend({...out,token});
 const status=(status,eventId='status_'+status,extra={})=>store.applyStatus({eventId,status,at:now(),providerId:'provider_notice',...extra});
 return {...f,store,ingress,capture,peerKey,token,...out,permit,status,now,ctx:()=>f.sqlite.prepare('SELECT * FROM sarin_wa_contexts').get(),out:()=>f.sqlite.prepare('SELECT * FROM sarin_wa_outbox').get()};
}
test('own_api_status_does_not_pause',async t=>{const f=await setup(t);await f.store.finishSend({...f,result:{status:'accepted',providerId:'provider_notice'}});await f.status('read','read',{from:'+573000000002',to:'+573000000001',wabaId:'12345'});assert.equal(f.ctx().paused,0);assert.equal(f.out().state,'read');assert.ok(f.out().delivered_at);await f.status('sent');assert.equal(f.out().state,'read');});
test('own_echo_with_provider_wamid_does_not_pause',async t=>{const f=await setup(t);await f.store.finishSend({...f,result:{status:'accepted',providerId:'provider_notice',wamid:'wamid.own+/='}});await f.capture('echo','wamid.own+/=');assert.equal(f.ctx().paused,0);assert.equal(f.sqlite.prepare("SELECT text FROM sarin_wa_inbox WHERE kind='echo'").get().text,null);});
test('ambiguous_echo_pauses',async t=>{const f=await setup(t);await f.store.finishSend({...f,result:{status:'accepted',providerId:'provider_notice'}});await f.capture('echo','wamid.unknown');assert.equal(f.ctx().paused,1);});
test('provider_identity_conflict_is_rejected',async t=>{const f=await setup(t);await f.store.finishSend({...f,result:{status:'accepted',providerId:'provider_notice',wamid:'wamid.own'}});await f.status('delivered','conflict',{wamid:'wamid.other'});assert.equal(f.out().conflict,1);assert.equal(f.out().delivered_at,null);assert.equal(f.ctx().paused,1);});
test('failed_after_delivered_preserves_evidence_and_revokes_permission',async t=>{const f=await setup(t);await f.store.finishSend({...f,result:{status:'accepted',providerId:'provider_notice'}});await f.status('delivered');const delivered=f.out().delivered_at;await f.status('failed');assert.equal(f.out().delivered_at,delivered);assert.equal(f.out().state,'delivered');assert.equal(f.out().conflict,1);assert.equal(f.ctx().paused,1);const revision=f.ctx().revision;await f.status('failed');assert.equal(f.ctx().revision,revision);});
test('status_before_post_result_keeps_wamid_and_delivery',async t=>{const f=await setup(t);await f.status('read','early',{externalId:f.permit.externalId,wamid:'wamid.early+/='});await f.store.finishSend({...f,result:{status:'accepted',providerId:'provider_notice',wamid:'wamid.early+/='}});assert.equal(f.out().wamid,'wamid.early+/=');assert.equal(f.out().state,'read');assert.equal(f.ctx().paused,0);});
test('conflicting_post_identity_is_durable_and_fail_closed',async t=>{const f=await setup(t);await f.status('read','early',{externalId:f.permit.externalId,wamid:'wamid.early'});await assert.rejects(f.store.finishSend({...f,result:{status:'accepted',providerId:'other_provider',wamid:'wamid.other'}}),e=>e.code==='work_conflict');assert.equal(f.out().conflict,1);assert.equal(f.ctx().paused,1);});
test('invalid_optional_status_identity_is_rejected',async t=>{const f=await setup(t);for(const change of [{from:'bad'},{to:''},{wabaId:'bad'},{wamid:'bad\n'}])await assert.rejects(f.status('sent','invalid',change),e=>e.code==='invalid_request');});

test('identity_conflict_duplicate_is_inert',async t=>{const f=await setup(t);await f.store.finishSend({...f,result:{status:'accepted',providerId:'provider_notice',wamid:'wamid.own'}});await f.status('delivered','bad',{wamid:'wamid.other'});const revision=f.ctx().revision;await f.status('delivered','bad',{wamid:'wamid.other'});assert.equal(f.ctx().revision,revision);assert.equal(f.sqlite.prepare('SELECT COUNT(*) n FROM sarin_wa_delivery_observations').get().n,1);});
test('concurrent_provider_binding_conflict_fails_closed',async t=>{const f=await setup(t);let interleaved=false;const db={prepare:f.db.prepare,async batch(statements){if(!interleaved&&statements.some(s=>s.sql.includes('INSERT INTO sarin_wa_delivery_observations'))){interleaved=true;await f.store.finishSend({...f,result:{status:'accepted',providerId:'winner',wamid:'wamid.winner'}});}return f.db.batch(statements);}};const raced=createWhatsAppWorkStore({db,now:f.now});await raced.applyStatus({eventId:'raced',providerId:'loser',externalId:f.permit.externalId,wamid:'wamid.loser',status:'read',at:f.now()});assert.equal(f.out().provider_id,'winner');assert.equal(f.out().conflict,1);assert.equal(f.ctx().paused,1);});

test('human_pause_during_post_does_not_hide_send_expiry',async t=>{const f=await setup(t);await f.capture('echo','wamid.human');const later=createWhatsAppWorkStore({db:f.db,now:()=>f.now()+120001});await later.expireLeases();assert.equal(f.out().state,'send_uncertain');assert.equal(f.sqlite.prepare('SELECT consumed FROM sarin_wa_send_quota').get().consumed,1);});
